import{_ as a}from"./chunks/flight_termination_logic_diagram.Dsd1Xat6.js";import{_ as t,c as i,o as r,al as o}from"./chunks/framework.D8UyiDWg.js";const u=JSON.parse('{"title":"Конфігурація завершення польоту","description":"","frontmatter":{},"headers":[],"relativePath":"uk/advanced_config/flight_termination.md","filePath":"uk/advanced_config/flight_termination.md"}'),n={name:"uk/advanced_config/flight_termination.md"};function l(c,e,s,m,h,f){return r(),i("div",null,e[0]||(e[0]=[o('<h1 id="конфігурація-завершення-польоту" tabindex="-1">Конфігурація завершення польоту <a class="header-anchor" href="#конфігурація-завершення-польоту" aria-label="Permalink to &quot;Конфігурація завершення польоту&quot;">​</a></h1><p>The <em>Flight termination</em> <a href="./../config/safety.html#failsafe-actions">failsafe action</a> irreversibly turns off controllers and sets PWM values to their parameter configured failsafe values.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Flight termination differs from the <a href="./../config/safety.html#kill-switch">Kill action</a> in that it is permanent until after reboot.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is <em>not</em> an independent <em>Flight Termination System</em>. Якщо втрачається живлення або автопілот повністю відмовляє, аварійні пристрої не будуть активовані.</p></div><h2 id="загальнии-огляд" tabindex="-1">Загальний огляд <a class="header-anchor" href="#загальнии-огляд" aria-label="Permalink to &quot;Загальний огляд&quot;">​</a></h2><h3 id="termination-triggers" tabindex="-1">Termination Triggers <a class="header-anchor" href="#termination-triggers" aria-label="Permalink to &quot;Termination Triggers&quot;">​</a></h3><p>Termination may be triggered by:</p><ul><li><a href="./../config/safety.html">Safety checks</a> for RC Loss, geofence violation, and so on (on any vehicle type or in any flight mode).</li><li><a href="./../config/safety.html#failure-detector">Failure Detector</a> trigger</li><li>RC termination switch (mapped to an RC channel using <a href="./../advanced_config/parameter_reference.html#RC_MAP_TERM_SW">RC_MAP_TERM_SW</a>).</li><li>The MAVLink <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_FLIGHTTERMINATION" target="_blank" rel="noreferrer">MAV_CMD_DO_FLIGHTTERMINATION</a> MAVLink command from a GCS or companion computer (see <a href="#mavlink-trigger">MAVLink Trigger</a> below).</li></ul><p>Немає можливості відновлення після аварійного припинення польоту. Після виклику аварійного припинення польоту вам слід якнайшвидше відключити батарею. Перед тим, як знову використовувати транспортний засіб, вам доведеться перезавантажити/вимкнути живлення.</p><h3 id="termination-actions" tabindex="-1">Termination Actions <a class="header-anchor" href="#termination-actions" aria-label="Permalink to &quot;Termination Actions&quot;">​</a></h3><p>Коли активується <em>аварійне припинення польоту</em>, PX4 одночасно вимикає всі контролери та встановлює всі виходи PWM у значення аварійного режиму.</p><p>Залежно від підключених пристроїв, вихідні значення аварійного режиму PWM можуть бути використані для:</p><ul><li>Розгорніть <a href="./../peripherals/parachute.html">парашут</a>.</li><li>Витягнути втягуючі стійки шасі.</li><li>Перемістіть гімбал, підключений до PWM, в безпечне положення (або втягніть його), щоб захистити камеру.</li><li>Запустіть надувний пристрій, наприклад подушку безпеки.</li><li>Запустити тривогу.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>PX4 не знає, які пристрої безпеки приєднані - він просто застосовує заздалегідь визначений набір значень ШІМ до своїх виходів.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Failsafe values are applied to all outputs on termination. Немає способу налаштувати незалежне тригерування моторів або конкретних пристроїв безпеки на основі часу (або іншого критерію).</p></div><h2 id="конфігурація-апаратного-забезпечення" tabindex="-1">Конфігурація апаратного забезпечення <a class="header-anchor" href="#конфігурація-апаратного-забезпечення" aria-label="Permalink to &quot;Конфігурація апаратного забезпечення&quot;">​</a></h2><p>Будь-який <em>пристрій безпеки</em> (наприклад, <a href="./../peripherals/parachute.html">парашут</a>), який може бути активований зміною значення PWM, може бути використаний та підключений до будь-якого вільного порту PWM (як MAIN, так і AUX).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Якщо ви використовуєте плату серії Pixhawk, вам доведеться окремо живити рейку сервопривода (наприклад, з 5V BEC, який часто також доступний з вашого регулятора обертів).</p></div><h2 id="конфігурація-програмного-забезпечення" tabindex="-1">Конфігурація програмного забезпечення <a class="header-anchor" href="#конфігурація-програмного-забезпечення" aria-label="Permalink to &quot;Конфігурація програмного забезпечення&quot;">​</a></h2><p>Тема <a href="./../config/safety.html">Безпека</a> пояснює, як встановити <em>аварійне припинення польоту</em> як <a href="./../config/safety.html#failsafe-actions">дію в разі аварії</a>, що має бути виконана для певної перевірки аварійного стану.</p><p><a href="./../config/safety.html#failure-detector">Виявник відмов</a> також (опційно) може бути налаштований на активацію аварійного припинення польоту, якщо транспортний засіб перекидається (перевищує певний кут нахилу) або якщо виявлена відмова зовнішньою автоматичною системою спрацьовування (ATS):</p><ul><li>Увімкніть виявник відмов під час польоту, встановивши <a href="./../advanced_config/parameter_reference.html#CBRK_FLIGHTTERM">CBRK_FLIGHTTERM=0</a>.</li><li><a href="./../config/safety.html#attitude-trigger">Safety &gt; Failure Detector &gt; Attitude Trigger</a> explains how to configure the attitude limits that trigger <em>Flight termination</em>.<div class="info custom-block"><p class="custom-block-title">INFO</p><p>During <em>takeoff</em> excessive attitutes will trigger <em>lockdown</em> (kill motors, but not launch parachute) rather than flight termination. This is always enabled, irrespective of the value of <code>CBRK_FLIGHTTERM</code>.</p></div></li></ul><p>:::</p><ul><li><a href="./../config/safety.html#external-automatic-trigger-system-ats">Safety &gt; External Automatic Trigger System (ATS)</a> explains how to configure an external trigger system.</li></ul><p>Для кожного основного виходу, до якого підключений пристрій безпеки, де &quot;n&quot; - номер порту PWM, встановіть:</p><ul><li><a href="./../config/safety.html#external-automatic-trigger-system-ats">Безпека &gt; Зовнішня автоматична система спрацьовування (ATS)</a> пояснює, як налаштувати зовнішню систему спрацьовування.</li><li><a href="./../advanced_config/parameter_reference.html#PWM_MAIN_FAIL1">PWM_MAIN_FAILn</a> to the device&#39;s &quot;ON&quot; PWM value.</li></ul><p>Для кожного основного виходу, до якого підключений пристрій безпеки, де &quot;n&quot; - номер порту PWM, встановіть:</p><ul><li><a href="./../advanced_config/parameter_reference.html#PWM_MAIN_DIS1">PWM_MAIN_DISn</a> до значення &quot;OFF&quot; PWM пристрою.</li><li><a href="./../advanced_config/parameter_reference.html#PWM_MAIN_FAIL1">PWM_MAIN_FAILn</a> до значення PWM пристрою &quot;ON&quot;.</li></ul><p>Для кожного AUX виходу, до якого підключений пристрій безпеки, де &quot;n&quot; - номер порту PWM, встановіть:</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Flight termination via ATS only works if <code>drivers/pwm_input</code> is included in the firmware for your board. If not, you need to add it manually to your board configuration using <a href="./../hardware/porting_guide_config.html#px4-menuconfig-setup">boardconfig</a>.</p></div><h2 id="mavlink-trigger" tabindex="-1">MAVLink Trigger <a class="header-anchor" href="#mavlink-trigger" aria-label="Permalink to &quot;MAVLink Trigger&quot;">​</a></h2><p>The <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_FLIGHTTERMINATION" target="_blank" rel="noreferrer">MAV_CMD_DO_FLIGHTTERMINATION</a> command can be used to trigger Flight termination from a ground station or companion computer.</p><p>This is sent, for example, when you call the <a href="https://mavsdk.mavlink.io/main/en/cpp/api_reference/classmavsdk_1_1_action.html#classmavsdk_1_1_action_1a47536c4a4bc8367ccd30a92eb09781c5" target="_blank" rel="noreferrer">MAVSDK Action plugin</a> <code>terminate()</code> or <code>terminate_async()</code> methods.</p><h2 id="схема-логіки" tabindex="-1">Схема логіки <a class="header-anchor" href="#схема-логіки" aria-label="Permalink to &quot;Схема логіки&quot;">​</a></h2><p>Нарешті, встановіть значення PWM для портів <code>PWM_AUX_FAILn</code> та <code>PWM_MAIN_FAILn</code> для будь-яких двигунів.</p><p><img src="'+a+'" alt="Logic diagram"></p>',36)]))}const g=t(n,[["render",l]]);export{u as __pageData,g as default};
